def f(g):
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    pts=[]
    for r,row in enumerate(g):
        for c,vv in enumerate(row):
            if vv!=bg: pts.append((r,c))
    byc={}
    for p_ in pts:
        v=g[p_[0]][p_[1]]; byc.setdefault(v,[]).append(p_)
    for v,ps in byc.items():
        ps=sorted(ps)
        runs=[]; cur=[ps[0]]
        for p,q in zip(ps,ps[1:]):
            if abs(q[0]-p[0])==1 and abs(q[1]-p[1])==1: cur.append(q)
            else: runs.append(cur); cur=[q]
        runs.append(cur)
        for run in runs:
            if len(run)<2: continue
            dr=run[-1][0]-run[0][0]; dc=run[-1][1]-run[0][1]
            # unit step: normalize sign
            if abs(dr)>0: s=dr//abs(dr)
            else: s=-1
            u=(s*abs(dr)/max(abs(dr),abs(dc)), s*(dc*abs(dr))/max(abs(dr),abs(dc))) if False else None
            # simpler: unit along the diagonal direction: signs of dr,dc
            u=(1 if dr>0 else -1, 1 if dc>0 else -1)
            for start,direct in ((run[0],u),(run[-1],(-u[0],-u[1]))):
                r,c=start
                rr,cc=r+direct[0],c+direct[1]
                while 0<=rr<H and 0<=cc<W and g[rr][cc]==bg:
                    out[rr][cc]=v; rr+=direct[0]; cc+=direct[1]
    return out

